{"predictors": [
  {
    "name": "Research and Development Intensity",
    "construction": "Annual R&D expenditure / market capitalization",
    "rationale": "Firms investing more in R&D may be more innovative, possibly leading to higher future earnings.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Advertising Expenditure Ratio",
    "construction": "Annual advertising expenditure / total sales",
    "rationale": "High advertising spending may signal superior product quality or market power.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Employee Satisfaction",
    "construction": "Survey data on employee satisfaction, standardized and rescaled",
    "rationale": "Firms with more satisfied employees may have lower turnover and higher productivity.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Executive Age",
    "construction": "Average age of the top five executives",
    "rationale": "Younger executives may be more innovative and growth-oriented.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Corporate Social Responsibility Score",
    "construction": "External ratings of firms' environmental, social, and governance performance",
    "rationale": "Responsible firms may attract socially conscious investors or customers, boosting returns.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Patent Quality",
    "construction": "Citations per patent, standardized and rescaled",
    "rationale": "High-quality patents may signal superior innovation and future growth.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "CEO-CFO Pay Ratio",
    "construction": "CEO total compensation / CFO total compensation",
    "rationale": "A high ratio may signal CEO overconfidence or poor governance.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Customer Concentration",
    "construction": "Sales to the largest customer / total sales",
    "rationale": "High customer concentration may increase business risk.",
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Geographic Diversification",
    "construction": "Number of distinct geographic markets in which the firm operates",
    "rationale": "More diversified firms may be less exposed to local economic shocks.",
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Supply Chain Complexity",
    "construction": "Number of distinct input categories in the firm's production process",
    "rationale": "Complex supply chains may be difficult to manage efficiently.",
    "higher_returns_for": "Low values of the measure"
  }
]}
